subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "as_of_date": {
      "maxLength": 10,
      "pattern": "^[0-9-]{1,10}$",
      "type": "string"
    },
    "dv01": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "fitted_curves": {
      "additionalProperties": {
        "properties": {
          "beta0": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "beta1": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "beta2": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "lambda": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "description": "Nelson-Siegel / Svensson fitted curves keyed by currency",
      "type": "object"
    },
    "fx_implied_differentials": {
      "additionalProperties": {
        "maxLength": 32,
        "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
        "type": "string"
      },
      "description": "Implied rate differentials from FX forwards",
      "type": "object"
    },
    "irs_par_rate": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "key_spreads": {
      "description": "Key rates spreads (2s10s, 5s30s, swap spreads, OAS)",
      "properties": {
        "2s10s_bps": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "5s30s_bps": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "swap_spread_10y_bps": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    },
    "scenario_shocks": {
      "description": "Parallel/twist/butterfly shock results",
      "properties": {
        "parallel_down_100": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "parallel_up_100": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "twist_flatten": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "twist_steepen": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    },
    "tool_calls": {
      "items": {
        "properties": {
          "count": {
            "type": "integer"
          },
          "name": {
            "maxLength": 64,
            "pattern": "^[A-Za-z0-9_-]+$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 200,
      "type": "array"
    },
    "traceability_table": {
      "items": {
        "properties": {
          "metric": {
            "maxLength": 200,
            "type": "string"
          },
          "source": {
            "maxLength": 200,
            "type": "string"
          },
          "value": {
            "maxLength": 200,
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 500,
      "type": "array"
    }
  },
  "required": [
    "as_of_date",
    "fitted_curves",
    "key_spreads",
    "tool_calls"
  ],
  "type": "object"
}

{
  "additionalProperties": false,
  "properties": {
    "as_of_date": {
      "description": "ISO date for the rates snapshot",
      "maxLength": 10,
      "pattern": "^[0-9-]{1,10}$",
      "type": "string"
    },
    "credit_spreads": {
      "additionalProperties": {
        "maxLength": 32,
        "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
        "type": "string"
      },
      "description": "Credit spreads by rating bucket and tenor, values in bps as strings",
      "type": "object"
    },
    "currencies": {
      "description": "Currency codes included in this snapshot",
      "items": {
        "maxLength": 3,
        "pattern": "^[A-Z]{3}$",
        "type": "string"
      },
      "maxItems": 20,
      "type": "array"
    },
    "curves": {
      "additionalProperties": {
        "additionalProperties": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "description": "Tenor-to-yield map",
        "type": "object"
      },
      "description": "Government and swap curves keyed by currency code, values are tenor-rate maps",
      "type": "object"
    },
    "fx": {
      "additionalProperties": {
        "properties": {
          "fwd_1m": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "fwd_3m": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "spot": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "description": "Spot and forward FX rates keyed by currency pair",
      "type": "object"
    },
    "macro": {
      "description": "Economic indicators and central bank rates",
      "properties": {
        "central_bank_rate": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "cpi_yoy": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "pmi": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    }
  },
  "required": [
    "as_of_date",
    "currencies",
    "curves"
  ],
  "type": "object"
}
